[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][string]$OutputDirectory,
    [Parameter(Mandatory=$true)][string]$AllowedRoot,
    [Parameter(Mandatory=$true)][string]$LaneProjectPath,
    [Parameter(Mandatory=$true)][ValidateRange(1,3)][int]$LaneNumber,
    [Parameter(Mandatory=$true)][ValidatePattern('^0x[0-9A-Fa-f]{8,16}$')][string]$AffinityMaskHex,
    [Parameter(Mandatory=$true)][ValidatePattern('^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$')][string]$WaveId,
    [Parameter(Mandatory=$true)][ValidatePattern('^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$')][string]$BarrierToken,
    [Parameter(Mandatory=$true)][string]$BarrierRoot,
    [string]$UnityPath='H:\UnityEditor\2022.3.30f1c1\Editor\Unity.exe',
    [switch]$BindingSmokeOnly,
    [switch]$SelfRelease,
    [ValidateRange(1,900)][int]$LicenseAdmissionTimeoutSeconds=300,
    [ValidateRange(1,900)][int]$BarrierTimeoutSeconds=300,
    [int]$TimeoutSeconds=1200
)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$utf8=New-Object Text.UTF8Encoding($false,$true)
function Convert-Json($Value,[int]$Depth=30){$t=($Value|ConvertTo-Json -Depth $Depth).Replace("`r`n","`n").Replace("`r","`n");if(-not$t.EndsWith("`n")){$t+="`n"};return $t}
function Write-CreateNew([string]$Path,$Value){if(Test-Path -LiteralPath $Path){throw "Create-new target exists: $Path"};$p=Split-Path -Parent $Path;if(-not(Test-Path $p)){New-Item -ItemType Directory -Path $p|Out-Null};$tmp=$Path+'.tmp-'+[Guid]::NewGuid().ToString('N');[IO.File]::WriteAllText($tmp,(Convert-Json $Value),$utf8);if(Test-Path $Path){throw "Create-new target appeared: $Path"};[IO.File]::Move($tmp,$Path)}
function Write-Atomic([string]$Path,$Value){$p=Split-Path -Parent $Path;if(-not(Test-Path $p)){New-Item -ItemType Directory -Path $p|Out-Null};$tmp=$Path+'.tmp-'+[Guid]::NewGuid().ToString('N');[IO.File]::WriteAllText($tmp,(Convert-Json $Value),$utf8);if(Test-Path $Path){$bak=$Path+'.bak-'+[Guid]::NewGuid().ToString('N');[IO.File]::Replace($tmp,$Path,$bak);if(Test-Path $bak){[IO.File]::Delete($bak)}}else{[IO.File]::Move($tmp,$Path)}}
function Is-Within([string]$Candidate,[string]$Root){$r=[IO.Path]::GetFullPath($Root).TrimEnd('\')+'\';return [IO.Path]::GetFullPath($Candidate).StartsWith($r,[StringComparison]::OrdinalIgnoreCase)}
function Read-Log([string]$Path){try{if(Test-Path $Path){return [IO.File]::ReadAllText($Path)}}catch{};return ''}
function Get-LaneUnity([string]$Path){return @(Get-CimInstance Win32_Process -Filter "Name='Unity.exe'" -ErrorAction SilentlyContinue|Where-Object{[string]$_.CommandLine-like('*'+$Path+'*')})}
function Get-StringHash([string]$Value){$s=[Security.Cryptography.SHA256]::Create();try{return([BitConverter]::ToString($s.ComputeHash($utf8.GetBytes($Value)))).Replace('-','').ToLowerInvariant()}finally{$s.Dispose()}}

$OutputDirectory=[IO.Path]::GetFullPath($OutputDirectory);$AllowedRoot=[IO.Path]::GetFullPath($AllowedRoot);$LaneProjectPath=[IO.Path]::GetFullPath($LaneProjectPath);$BarrierRoot=[IO.Path]::GetFullPath($BarrierRoot);$UnityPath=[IO.Path]::GetFullPath($UnityPath)
$expectedLane=[IO.Path]::GetFullPath(('H:\DDM_Final_Project_Gate13R48H\v1\lane-{0:D2}'-f$LaneNumber));if($LaneProjectPath-ne$expectedLane){throw 'Lane root mismatch.'};if(-not(Is-Within $OutputDirectory $BarrierRoot)-or-not(Is-Within $BarrierRoot $AllowedRoot)){throw 'Probe path escapes authorized verification root.'}
if($BindingSmokeOnly){Write-Output("BINDING-SMOKE-PASSED|Run-Gate13R48h3LaneLicenseProbeV1|$LaneNumber|$WaveId");exit 0}
if(-not(Test-Path $BarrierRoot -PathType Container)-or-not(Test-Path $LaneProjectPath -PathType Container)-or-not(Test-Path $UnityPath -PathType Leaf)){throw 'Required root/executable missing.'};if(Test-Path (Join-Path $LaneProjectPath 'Temp\UnityLockfile')-or@(Get-LaneUnity $LaneProjectPath).Count){throw 'Lane is not quiescent.'};if(Test-Path $OutputDirectory){throw 'Create-new probe output exists.'}
$log=$OutputDirectory+'.Unity.log';$admission=$OutputDirectory+'.license-admission.json';$summary=$OutputDirectory+'.probe-wrapper-summary.json';$failure=$OutputDirectory+'.probe-wrapper-failure.json';$ready=Join-Path $OutputDirectory 'method-ready.json';$release=Join-Path $BarrierRoot 'barrier-release.json';foreach($p in @($log,$admission,$summary,$failure)){if(Test-Path $p){throw "Create-new sidecar exists: $p"}}
$mask=[Convert]::ToUInt64($AffinityMaskHex.Substring(2),16);$expected=@('0x000000FF','0x0000FF00','0x00FF0000');if($AffinityMaskHex.ToUpperInvariant()-ne$expected[$LaneNumber-1]){throw 'Affinity mismatch.'}
$started=[DateTimeOffset]::Now;$proc=$null;$procStartTimeUtc=$null;$admitted=$false;$admittedAt=$null;$errors=New-Object Collections.Generic.List[string];$exit=-1
try{$args=@('-batchmode','-nographics','-quit','-projectPath',('"'+$LaneProjectPath+'"'),'-executeMethod','DDM.Research.Editor.Gate13R48h3LaneBatchCommandV1.ProbeLicenseBarrier','-ddmGate13ROutputDirectory',('"'+$OutputDirectory+'"'),'-ddmGate13RBarrierRoot',('"'+$BarrierRoot+'"'),'-ddmGate13RMethodReadyPath',('"'+$ready+'"'),'-ddmGate13RBarrierReleasePath',('"'+$release+'"'),'-ddmGate13RWaveId',$WaveId,'-ddmGate13RBarrierToken',$BarrierToken,'-ddmGate13RBarrierTimeoutSeconds',[string]$BarrierTimeoutSeconds,'-logFile',('"'+$log+'"'));$proc=Start-Process -FilePath $UnityPath -ArgumentList $args -WorkingDirectory (Split-Path -Parent $UnityPath) -WindowStyle Hidden -PassThru;$procStartTimeUtc=$proc.StartTime.ToUniversalTime().ToString('o');$proc.ProcessorAffinity=[IntPtr]([Int64]$mask);$proc.PriorityClass=[Diagnostics.ProcessPriorityClass]::Normal;$deadline=(Get-Date).AddSeconds($LicenseAdmissionTimeoutSeconds);while(-not$admitted){$proc.Refresh();$text=Read-Log $log;if($text-match'No valid Unity Editor license found|License is not active \(com\.unity\.editor\.headless\)'){throw 'Terminal Unity license/entitlement error.'};if($text-match'Serial number assigned to'){$admitted=$true;$admittedAt=[DateTimeOffset]::Now;Write-CreateNew $admission ([ordered]@{schemaVersion=1;admissionKind='gate13r-48h-three-lane-license-admission-v1';executionDesignId='gate13r-48h-10pct-three-isolated-editor-lanes-serial-license-admission-v1';waveId=$WaveId;lane=$LaneNumber;processId=$proc.Id;processStartTimeUtc=$procStartTimeUtc;startedAt=$started.ToString('o');admittedAt=$admittedAt.ToString('o');admissionSeconds=($admittedAt-$started).TotalSeconds;serialAssignmentPatternFound=$true;terminalLicensePatternFound=$false;barrierTokenSha256=Get-StringHash $BarrierToken;formalCampaign=$false});break};if($proc.HasExited){throw 'Unity exited before serial assignment.'};if((Get-Date)-ge$deadline){throw 'License admission timeout.'};Start-Sleep -Milliseconds 100};if($SelfRelease){$rdeadline=(Get-Date).AddSeconds($BarrierTimeoutSeconds);while(-not(Test-Path $ready)){if($proc.HasExited){throw 'Unity exited before method-ready.'};if((Get-Date)-ge$rdeadline){throw 'Method-ready timeout.'};Start-Sleep -Milliseconds 50;$proc.Refresh()};Write-CreateNew $release ([ordered]@{schemaVersion=1;releaseKind='gate13r-48h-three-lane-wave-release-v1';executionDesignId='gate13r-48h-10pct-three-isolated-editor-lanes-serial-license-admission-v1';waveId=$WaveId;barrierToken=$BarrierToken;laneCount=3;releasedAtUtc=[DateTime]::UtcNow.ToString('o');formalCampaign=$false})};$deadline=(Get-Date).AddSeconds($TimeoutSeconds);while(-not$proc.HasExited){if((Get-Date)-ge$deadline){throw 'Probe hard timeout.'};Start-Sleep -Milliseconds 200;$proc.Refresh()};$proc.Refresh();$exit=[int]$proc.ExitCode}catch{$errors.Add($_.Exception.ToString());if($null-ne$proc-and-not$proc.HasExited){&taskkill.exe /PID $proc.Id /T /F 2>&1|Out-Null}}
$q=(Get-Date).AddSeconds(60);do{$owned=@(Get-LaneUnity $LaneProjectPath);$lock=Test-Path (Join-Path $LaneProjectPath 'Temp\UnityLockfile');if(-not$owned.Count-and-not$lock){break};Start-Sleep -Milliseconds 250}while((Get-Date)-lt$q);$owned=@(Get-LaneUnity $LaneProjectPath);$lock=Test-Path (Join-Path $LaneProjectPath 'Temp\UnityLockfile');$result=Join-Path $OutputDirectory 'barrier-probe-result.json';if(-not$admitted){$errors.Add('Admission evidence missing.')};if($exit-ne0){$errors.Add("Unity exit code $exit.")};if(-not(Test-Path $ready)){$errors.Add('Method-ready missing.')};if(-not(Test-Path $result)){$errors.Add('Barrier probe result missing.')}else{$r=Get-Content -Raw $result|ConvertFrom-Json;if($r.passed-ne$true-or$r.planningWorkloadExecuted-ne$false-or[string]$r.waveId-ne$WaveId){$errors.Add('Barrier probe result invalid.')}};if($owned.Count-or$lock){$errors.Add('Residual process or lock.')};$done=[DateTimeOffset]::Now;$passed=$errors.Count-eq0;Write-Atomic $summary ([ordered]@{schemaVersion=1;summaryKind='gate13r-48h-three-lane-license-probe-wrapper-v1';completedAtUtc=[DateTime]::UtcNow.ToString('o');waveId=$WaveId;lane=$LaneNumber;processId=if($null-ne$proc){$proc.Id}else{$null};processStartTimeUtc=$procStartTimeUtc;startedAt=$started.ToString('o');admittedAt=if($null-ne$admittedAt){$admittedAt.ToString('o')}else{$null};completedAt=$done.ToString('o');wallSeconds=($done-$started).TotalSeconds;licenseAdmissionSeconds=if($null-ne$admittedAt){($admittedAt-$started).TotalSeconds}else{$null};unityExitCode=$exit;serialAssigned=$admitted;planningWorkloadExecuted=$false;residualProcessCount=$owned.Count;residualLock=$lock;errors=$errors.ToArray();formalCampaign=$false;passed=$passed})
if(-not$passed){Write-Atomic $failure ([ordered]@{schemaVersion=1;failureKind='gate13r-48h-three-lane-license-probe-failure-v1';failedAtUtc=[DateTime]::UtcNow.ToString('o');waveId=$WaveId;lane=$LaneNumber;errors=$errors.ToArray();formalCampaign=$false;automaticRetryAttempted=$false});Write-Error($errors-join'; ');exit 1};Write-Host("License/barrier probe passed: $WaveId lane $LaneNumber")-ForegroundColor Green;exit 0
